/** Static hydrangea clusters for the Lite tier (no WebGL) – a plain image, generated by scripts/gen-lite-flowers.mjs. */
export function LiteFlowers() {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- decorative SVG; next/image adds nothing for vector art
    <img src="/lite-flowers.svg" alt="" aria-hidden className="scene-bg h-full w-full object-cover opacity-90" decoding="async" fetchPriority="low" />
  );
}
